public class FloatingService extends Service {
    final ExecutorService worker=Executors.newSingleThreadExecutor(); final Handler handler=new Handler(Looper.getMainLooper());
    final ArrayList<Hit> hits=new ArrayList<>(); final String[] types={"Todos os formatos (número/texto)","Int8/UInt8","Int16","UInt16","Int32","UInt32","Int64","UInt64","Float32","Float64","Texto UTF-8","Texto UTF-16LE","Bytes (hex)"};
    WindowManager wm; View panel,bubble; TextView target,status; Spinner type; EditText query,replacement; LinearLayout resultList; WindowManager.LayoutParams panelParams,bubbleParams; Switch freezeToggle; int pid=-1,frozenPid=-1; String packageName=""; boolean scanning=false,targetFrozen=false,freezeRequested=false,updatingFreezeToggle=false;
    static class Hit {long address;String value;int typeIndex;Hit(long a,String v,int t){address=a;value=v;typeIndex=t;}}
    @Override public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}startNotice();wm=(WindowManager)getSystemService(WINDOW_SERVICE);buildPanel();showBubble();}
    @Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}
    void startNotice(){String channel="memory_root_overlay";if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(channel,"Janela flutuante Memória Root",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}Notification n=new Notification.Builder(this,channel).setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Memória Root ativo").setContentText("A janela flutuante acompanha o app em primeiro plano").build();startForeground(17,n);}
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);return t;}
    EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setTextColor(Color.WHITE);e.setHintTextColor(0xffc6cbd1);e.setHint(hint);return e;}
    Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);return b;}
    void buildPanel(){
        LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(7),dp(12),dp(8));box.setBackground(round(0xf0212935,dp(18)));
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView title=label("MEMÓRIA ROOT",15);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button minimize=button("—"),close=button("×");bar.addView(minimize);bar.addView(close);box.addView(bar);
        target=label("Detectando app…",11);box.addView(target);status=label("Preparando root…",11);box.addView(status);freezeToggle=new Switch(this);freezeToggle.setText("Congelar app durante a busca");freezeToggle.setTextColor(Color.WHITE);freezeToggle.setChecked(false);freezeToggle.setOnCheckedChangeListener((v,checked)->{if(!updatingFreezeToggle){freezeRequested=checked;if(pid>0&&checked!=targetFrozen)setTargetFrozen(checked);}});box.addView(freezeToggle);
        type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types){@Override public View getView(int p,View c,android.view.ViewGroup g){TextView t=(TextView)super.getView(p,c,g);t.setTextColor(Color.WHITE);return t;}});box.addView(type);
        query=field("Valor conhecido (ex.: moedas)");box.addView(query);
        LinearLayout row=new LinearLayout(this);Button find=button("Buscar"), refine=button("Refinar"), write=button("Gravar");row.addView(find,new LinearLayout.LayoutParams(0,-2,1));row.addView(refine,new LinearLayout.LayoutParams(0,-2,1));row.addView(write,new LinearLayout.LayoutParams(0,-2,1));box.addView(row);
        replacement=field("Novo valor");box.addView(replacement);ScrollView sc=new ScrollView(this);resultList=new LinearLayout(this);resultList.setOrientation(1);sc.addView(resultList);box.addView(sc,new LinearLayout.LayoutParams(-1,dp(125)));
        panel=box;panelParams=params(dp(300),-2);panelParams.gravity=Gravity.TOP|Gravity.END;panelParams.x=dp(10);panelParams.y=dp(70);panelParams.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE;
        bar.setOnTouchListener(new View.OnTouchListener(){int sx,sy,ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){sx=(int)e.getRawX();sy=(int)e.getRawY();ox=panelParams.x;oy=panelParams.y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){panelParams.x=ox+sx-(int)e.getRawX();panelParams.y=oy+(int)e.getRawY()-sy;wm.updateViewLayout(panel,panelParams);return true;}return e.getAction()==MotionEvent.ACTION_UP;}});
        minimize.setOnClickListener(v->showBubble());close.setOnClickListener(v->stopSelf());find.setOnClickListener(v->scan(false));refine.setOnClickListener(v->scan(true));write.setOnClickListener(v->writeAll());
    }
    GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    WindowManager.LayoutParams params(int width,int height){return new WindowManager.LayoutParams(width,height,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);}
    void showBubble(){handler.removeCallbacks(poll);if(targetFrozen&&frozenPid>0){int old=frozenPid;targetFrozen=false;frozenPid=-1;worker.execute(()->root("kill -CONT "+old));}if(panel!=null&&panel.getParent()!=null)wm.removeView(panel);if(bubble==null){TextView b=label("MR",15);b.setGravity(Gravity.CENTER);b.setTypeface(null,1);b.setBackground(round(0xff23a6a0,dp(28)));bubble=b;b.setOnClickListener(v->showPanel());bubbleParams=params(dp(54),dp(54));bubbleParams.flags|=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;bubbleParams.gravity=Gravity.TOP|Gravity.END;bubbleParams.x=dp(8);bubbleParams.y=dp(120);b.setOnTouchListener(new View.OnTouchListener(){int sx,sy,ox,oy;boolean drag;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){sx=(int)e.getRawX();sy=(int)e.getRawY();ox=bubbleParams.x;oy=bubbleParams.y;drag=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){int dx=sx-(int)e.getRawX(),dy=(int)e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>dp(12))drag=true;if(drag){bubbleParams.x=ox+dx;bubbleParams.y=oy+dy;wm.updateViewLayout(bubble,bubbleParams);}return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(!drag)v.performClick();return true;}return false;}});}if(bubble.getParent()==null)wm.addView(bubble,bubbleParams);}
    void showPanel(){if(bubble!=null&&bubble.getParent()!=null)wm.removeView(bubble);if(panel.getParent()==null)wm.addView(panel,panelParams);handler.removeCallbacks(poll);handler.post(poll);if(pid>0&&freezeRequested&&!targetFrozen)setTargetFrozen(true);}
    final Runnable poll=new Runnable(){public void run(){if(isAdded()){worker.execute(()->{String out=root("dumpsys activity activities | grep -E 'topResumedActivity|mResumedActivity|ResumedActivity' | tail -n 2");Matcher m=Pattern.compile("([A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+)/").matcher(out);String pkg="";while(m.find())pkg=m.group(1);if(pkg.isEmpty()){Matcher w=Pattern.compile("mCurrentFocus.*? ([A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+)/").matcher(root("dumpsys window | grep mCurrentFocus | head -n 1"));if(w.find())pkg=w.group(1);}String found="";if(!pkg.isEmpty())found=root("pidof "+pkg);int p=-1;try{if(!found.trim().isEmpty())p=Integer.parseInt(found.trim().split("\\s+")[0]);}catch(Exception ignored){}final String fp=pkg;final int fpid=p;handler.post(()->updateTarget(fp,fpid));});}handler.postDelayed(this,1800);}};
    boolean isAdded(){return panel!=null&&panel.getParent()!=null;}
    void updateTarget(String pkg,int nextPid){if(pkg==null||pkg.isEmpty()){target.setText("App em primeiro plano: não identificado");return;}if(nextPid<=0){target.setText("App: "+pkg+" (PID indisponível)");return;}if(nextPid!=pid){if(targetFrozen&&frozenPid>0){int old=frozenPid;worker.execute(()->root("kill -CONT "+old));targetFrozen=false;frozenPid=-1;}pid=nextPid;packageName=pkg;hits.clear();render();target.setText("App ativo: "+pkg+"  ·  "+pid);status.setText("Alvo atualizado; faça uma nova busca.");if(freezeRequested)setTargetFrozen(true);}else{target.setText("App ativo: "+pkg+"  ·  "+pid);}}
    boolean canFreeze(String pkg){return pkg!=null&&!pkg.equals(getPackageName())&&!pkg.equals("android")&&!pkg.startsWith("com.android.")&&!pkg.startsWith("com.miui.")&&!pkg.startsWith("com.mi.")&&!pkg.startsWith("com.xiaomi.")&&!pkg.contains("launcher")&&!pkg.contains("systemui")&&!pkg.contains("settings");}
    void setTargetFrozen(boolean freeze){if(pid<=0){status.setText("Nenhum processo alvo para congelar.");return;}if(!canFreeze(packageName)){status.setText("Alvo do sistema protegido: abra o jogo antes de congelar.");return;}final int targetPid=pid;targetFrozen=freeze;frozenPid=freeze?targetPid:-1;status.setText(freeze?"Congelando jogo…":"Retomando jogo…");worker.execute(()->{String out=root("kill -"+(freeze?"STOP ":"CONT ")+targetPid);handler.post(()->{if(out.startsWith("ERROR:")){targetFrozen=false;frozenPid=-1;freezeRequested=false;updatingFreezeToggle=true;freezeToggle.setChecked(false);updatingFreezeToggle=false;status.setText("Falha no sinal root: "+out);return;}if(pid==targetPid)status.setText(freeze?"Jogo congelado para a busca.":"Jogo retomado. Recolha a janela para alterar o valor.");});});}
    void scan(boolean refine){
        if(pid<=0){status.setText("Nenhum app alvo detectado.");return;}
        String needle=query.getText().toString().trim();
        if(needle.isEmpty()){status.setText("Digite um valor para buscar.");return;}
        int selected=type.getSelectedItemPosition();
        LinkedHashMap<Integer,String> patterns=patterns(needle,selected);
        if(patterns.isEmpty()){status.setText("Valor inválido para o tipo escolhido.");return;}
        ArrayList<Hit> old=new ArrayList<>(hits);
        status.setText("Buscando…");
        final int searchingPid=pid;
        worker.execute(()->{
            ArrayList<Hit> found=new ArrayList<>();long bytesScanned=0;
            for(Map.Entry<Integer,String> entry:patterns.entrySet()){
                int valueType=entry.getKey();ArrayList<Hit> prior=new ArrayList<>();
                if(refine)for(Hit h:old)if(h.typeIndex==valueType)prior.add(h);
                if(refine&&prior.isEmpty())continue;
                String out=root(scanCommand(searchingPid,entry.getValue(),prior));
                if(out.startsWith("ERROR:")){String error=out;handler.post(()->status.setText("Falha de acesso: "+error));return;}
                int limit=patterns.size()>1?75:250,added=0;
                for(String line:out.split("\\n")){if(line.startsWith("#BYTES=")){try{bytesScanned+=Long.parseLong(line.substring(7));}catch(Exception ignored){}continue;}try{found.add(new Hit(Long.parseLong(line.trim()),needle,valueType));if(++added>=limit)break;}catch(Exception ignored){}}
            }
            final long totalBytes=bytesScanned;handler.post(()->{if(pid!=searchingPid){status.setText("O app ativo mudou; descartei os resultados.");return;}hits.clear();hits.addAll(found);render();status.setText(found.isEmpty()?(totalBytes==0?(refine?"Refinamento sem correspondências.":"Leitura de memória bloqueada: 0 bytes acessíveis."):"0 resultados após ler "+totalBytes+" bytes. Tente o formato texto/bytes ou confira a representação."):"Endereços encontrados: "+hits.size());});
        });
    }
    LinkedHashMap<Integer,String> patterns(String value,int selected){LinkedHashMap<Integer,String> map=new LinkedHashMap<>();if(selected==0){for(int i=1;i<=12;i++){String p=hex(value,i);if(p!=null)map.put(i,p);}}else{int i=selected;String p=hex(value,i);if(p!=null)map.put(i,p);}return map;}
    String scanCommand(int pid,String pattern,ArrayList<Hit> prior){StringBuilder c=new StringBuilder("p="+pid+"; pat='"+pattern+"'; ");if(!prior.isEmpty()){c.append("for a in");for(Hit h:prior)c.append(" ").append(h.address);c.append("; do x=$(dd if=/proc/$p/mem bs=1 skip=$a count=").append(pattern.split(",").length).append(" 2>/dev/null | od -An -v -t x1 | tr -s ' ' | sed 's/^ //;s/ /,/g;s/,$//'); [ \"$x\" = \"$pat\" ] && echo $a; done");}else c.append("echo 'QkVHSU57bj1zcGxpdChwYXQscCwiLCIpfSB7Zm9yKGk9MTtpPD1ORjtpKyspe2JbKytrXT0kaTtpZihrPj1uKXtvaz0xO2ZvcihqPTE7ajw9bjtqKyspaWYocFtqXSE9Ij8/IiYmdG9sb3dlcihiW2stbitqXSkhPXBbal0pb2s9MDtpZihvayl7YT1iYXNlK2stbjtpZihhPj1sbyYmYTxoaSlwcmludCBhfX19fSBFTkR7cHJpbnQgIiNCWVRFUz0iIGt9' | base64 -d > /data/local/tmp/memoria_root_scan.awk || exit 1; while read s e perms rest; do case $perms in *r*) ;; *) continue;; esac; start=$((16#$s)); end=$((16#$e)); block=4096; cur=$start; while [ $cur -lt $end ]; do chunk=$((cur+67108864)); [ $chunk -gt $end ] && chunk=$end; off=$((cur/block)); base=$((off*block)); count=$(((chunk-base+block-1)/block)); dd if=/proc/$p/mem bs=$block skip=$off count=$count 2>/dev/null | od -An -v -t x1 | awk -v pat=$pat -v base=$base -v lo=$cur -v hi=$chunk -f /data/local/tmp/memoria_root_scan.awk; cur=$chunk; done; done < /proc/$p/maps");return c.toString();}    String hex(String s,int t){try{if(t==10)return bytes(s.getBytes("UTF-8"));if(t==11)return bytes(s.getBytes("UTF-16LE"));if(t==12){String[] a=s.split("[ ,]+",-1);StringBuilder out=new StringBuilder();for(String x:a){if(!x.equals("??")&&!x.equals("?")){int v=Integer.parseInt(x.replace("0x",""),16);if(v<0||v>255)return null;x=String.format(Locale.US,"%02x",v);}else x="??";if(out.length()>0)out.append(',');out.append(x);}return out.toString();}java.nio.ByteBuffer b;switch(t){case 1:{int v=Integer.parseInt(s);if(v< -128||v>255)return null;b=java.nio.ByteBuffer.allocate(1).order(java.nio.ByteOrder.LITTLE_ENDIAN).put((byte)v);break;}case 2:b=java.nio.ByteBuffer.allocate(2).order(java.nio.ByteOrder.LITTLE_ENDIAN).putShort(Short.parseShort(s));break;case 3:{int v=Integer.parseInt(s);if(v<0||v>65535)return null;b=java.nio.ByteBuffer.allocate(2).order(java.nio.ByteOrder.LITTLE_ENDIAN).putShort((short)v);break;}case 4:b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt(Integer.parseInt(s));break;case 5:{long v=Long.parseLong(s);if(v<0||v>0xffffffffL)return null;b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt((int)v);break;}case 6:b=java.nio.ByteBuffer.allocate(8).order(java.nio.ByteOrder.LITTLE_ENDIAN).putLong(Long.parseLong(s));break;case 7:{java.math.BigInteger v=new java.math.BigInteger(s);if(v.signum()<0||v.bitLength()>64)return null;byte[] raw=v.toByteArray(),little=new byte[8];for(int i=0;i<Math.min(8,raw.length);i++)little[i]=raw[raw.length-1-i];b=java.nio.ByteBuffer.wrap(little);break;}case 8:b=java.nio.ByteBuffer.allocate(4).order(java.nio.ByteOrder.LITTLE_ENDIAN).putFloat(Float.parseFloat(s));break;default:b=java.nio.ByteBuffer.allocate(8).order(java.nio.ByteOrder.LITTLE_ENDIAN).putDouble(Double.parseDouble(s));}return bytes(b.array());}catch(Exception e){return null;}}String bytes(byte[] a){StringBuilder b=new StringBuilder();for(byte v:a){if(b.length()>0)b.append(',');b.append(String.format(Locale.US,"%02x",v&255));}return b.toString();}
    void render(){if(resultList==null)return;resultList.removeAllViews();for(Hit h:hits){TextView r=label(String.format(Locale.US,"0x%X  ·  %s  ·  %s",h.address,types[h.typeIndex],h.value),12);r.setPadding(dp(4),dp(5),0,dp(5));r.setOnClickListener(v->editOne(h));resultList.addView(r);}}
    void writeAll(){String value=replacement.getText().toString().trim();if(hits.isEmpty()){status.setText("Sem resultados.");return;}int targetPid=pid;ArrayList<Hit> copy=new ArrayList<>(hits);worker.execute(()->{StringBuilder c=new StringBuilder();for(Hit h:copy){String pat=hex(value,h.typeIndex);if(pat!=null)c.append("printf '%b' '\\x").append(pat.replace(",","\\x")).append("' | dd of=/proc/").append(targetPid).append("/mem bs=1 seek=").append(h.address).append(" conv=notrunc 2>/dev/null; ");}String o=root(c.toString());handler.post(()->status.setText(o.startsWith("ERROR:")?o:"Gravação concluída."));});status.setText("Gravando…");}
    void editOne(Hit h){EditText e=field("Novo valor");new AlertDialog.Builder(this).setTitle(String.format(Locale.US,"Editar 0x%X · %s",h.address,types[h.typeIndex])).setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Gravar",(d,w)->{String pat=hex(e.getText().toString().trim(),h.typeIndex);if(pat==null||pat.contains("??")){status.setText("Informe bytes concretos para gravar.");return;}int p=pid;String cmd="printf '%b' '\\x"+pat.replace(",","\\x")+"' | dd of=/proc/"+p+"/mem bs=1 seek="+h.address+" conv=notrunc 2>/dev/null";worker.execute(()->{String o=root(cmd);handler.post(()->status.setText(o.startsWith("ERROR:")?o:"Gravação concluída."));});}).show();}
    String root(String cmd){try{java.lang.Process p=new ProcessBuilder("su","-c",cmd).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] a=new byte[8192];int n;while((n=p.getInputStream().read(a))!=-1)b.write(a,0,n);int code=p.waitFor();return code==0?b.toString("UTF-8"):"ERROR: "+b.toString("UTF-8");}catch(Exception e){return "ERROR: "+e.getMessage();}}
    @Override public void onDestroy(){handler.removeCallbacks(poll);if(targetFrozen&&frozenPid>0)root("kill -CONT "+frozenPid);if(panel!=null&&panel.getParent()!=null)wm.removeView(panel);if(bubble!=null&&bubble.getParent()!=null)wm.removeView(bubble);worker.shutdownNow();stopForeground(true);super.onDestroy();}
    @Override public IBinder onBind(Intent i){return null;}
}
